using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Connects an affiliate program to the given affiliate. Returns information about the connected affiliate program
    /// </summary>
    public Task<TdLib.TdApi.Objects.ConnectedAffiliateProgram> ConnectAffiliateProgramAsync(AffiliateType affiliate = default, long botUserId = default)
    {

           using var activity =  StartCallActivity("ConnectAffiliateProgramAsync", typeof(ConnectAffiliateProgram).FullName ?? "ConnectAffiliateProgramAsync");

           try
           {
             return client.ConnectAffiliateProgramAsync(affiliate, botUserId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
